// Customer identifiers are not order references. Keep the original bank reference unchanged.
function stripCustomerReference(text) {
  return String(text ?? '').replace(/\b(?:Kunde|Kundennummer|Kunden[-_\s]*Nr\.?)\s*[:#]?\s*(?:NT[-_\s]*)?NEON[-_\s]*T?\s*#?\s*\d{4}(?![A-Z0-9])/gi, ' ');
}
// NEONTRIP Qonto Webhook - Validate & Extract
// Mit 2-Stufen Erkennung für falsch geschriebene Referenzen

try {
  const input = $input.first().json;
  const body = input.body || input;

  // Debug: Rohdaten speichern für Fehlerfall
  const rawData = JSON.stringify(body, null, 2).substring(0, 1000);

  // Transaction extrahieren - Qonto Webhook sendet: body.data
  let tx = body.data || body.transaction || body;

  // Prüfen ob wir überhaupt eine gültige Transaction haben
  if (!tx || typeof tx !== 'object') {
    return [{
      json: {
        stop: true,
        reason: 'invalid_webhook_data',
        sendEmail: true,
        emailSubject: 'N8N Fehler: Ungültige Webhook-Daten von Qonto',
        emailBody: `PROBLEM: Ungültige Webhook-Daten\n\nROHDATEN:\n${rawData}`,
        respond: { status: 200 }
      }
    }];
  }

  // Prüfen ob side-Feld existiert
  if (tx.side === undefined || tx.side === null) {
    return [{
      json: {
        stop: true,
        reason: 'missing_side_field',
        sendEmail: true,
        emailSubject: 'N8N Fehler: Qonto Webhook ohne "side" Feld',
        emailBody: `PROBLEM: side-Feld fehlt\n\nVerfügbare Felder: ${Object.keys(tx).join(', ')}\n\nROHDATEN:\n${rawData}`,
        respond: { status: 200 }
      }
    }];
  }

  if (tx.side !== 'credit') {
    return [{ json: { stop: true, reason: 'not_credit', respond: { status: 200 } } }];
  }

  // PayPal balance payouts to our bank are internal transfers, not customer payments.
  const paypalSender = [tx.label, tx.counterparty_name, tx.counterparty?.name, tx.counterparty?.label]
    .some(value => /^paypal(?:$|[\s*.,(])/i.test(String(value || '').trim()));
  if (paypalSender) {
    return [{ json: { stop: true, reason: 'paypal_balance_payout', sendEmail: false, respond: { status: 200 } } }];
  }

  const reference = String(tx.reference || tx.label || '');
  const normalizedReference = reference
    .normalize('NFKC')
    .replace(/[\u00A0]/g, ' ')
    .replace(/[‐‑‒–—]/g, '-');
  const amount = Math.abs(parseFloat(tx.amount || tx.local_amount || 0));

  // "Molli" still ignorieren
  if (reference.toLowerCase().includes('molli')) {
    return [{ json: { stop: true, reason: 'molli_transaction', respond: { status: 200 } } }];
  }

  // ===== STUFE 1: Strenge NEON-Regex =====
  // NEONT-Bestellnummern bestehen verbindlich aus genau vier Ziffern.
  // Datum, Rechnungsnummer oder weiterer Freitext hinter der Bestellnummer
  // darf niemals Bestandteil der Shopify-Referenz werden.
  const neonRegex = /(?:^|[^A-Z0-9])(?:PF[-_\s]*)?R?NEON[-_\s]*T?\s*#?\s*(\d{4})(?![A-Z0-9])/i;
  const orderReference = stripCustomerReference(normalizedReference);
  let match = orderReference.match(neonRegex);
  let fuzzyMatch = false;

  // ===== STUFE 2: Fuzzy Matching für Beträge > 100€ =====
  if (!match && amount > 100) {
    // Suche nach 4-stelliger Zahl die eine Order-Nummer sein könnte
    // Typische NEONT-Nummern: 3xxx, 4xxx
    const fuzzyRegex = /\b([3-9]\d{3})\b/;
    const fuzzyResult = orderReference.match(fuzzyRegex);

    if (fuzzyResult) {
      match = fuzzyResult;
      fuzzyMatch = true;
    }
  }

  if (!match) {
    // Kein Match gefunden
    if (amount > 100) {
      // Größerer Betrag ohne erkennbare Referenz → Email-Alert
      return [{
        json: {
          stop: true,
          reason: 'no_reference_high_amount',
          sendEmail: true,
          emailSubject: 'N8N Prüfen: Zahlung ohne NEON-Referenz (€' + amount.toFixed(2) + ')',
          emailBody: `══════════════════════════════════════════════
MANUELLE PRÜFUNG ERFORDERLICH
══════════════════════════════════════════════

Eine Gutschrift über €${amount.toFixed(2)} ist eingegangen, aber keine NEON-Referenz wurde erkannt.

TRANSAKTIONS-DETAILS:
• Betrag: €${amount.toFixed(2)}
• Von: ${tx.label || tx.counterparty_name || 'Unbekannt'}
• Verwendungszweck: ${reference}
• Qonto Transaction ID: ${tx.id || 'N/A'}
• Datum: ${tx.settled_at || tx.emitted_at || 'N/A'}

AKTION ERFORDERLICH:
Bitte prüfen ob diese Zahlung einer Bestellung zugeordnet werden kann.`,
          respond: { status: 200 }
        }
      }];
    }
    // Kleiner Betrag ohne NEON → still ignorieren
    return [{ json: { stop: true, reason: 'no_neon_reference', respond: { status: 200 } } }];
  }

  // Normalisiere zu NEONTXXXX Format
  const neonNumber = 'NEONT' + match[1];
  const amountCents = Math.round(amount * 100);
  const customerIdentityCandidates = Array.from(new Set([
    tx.counterparty_name,
    tx.counterparty?.name,
    tx.counterparty?.label,
    tx.initiator?.name,
    tx.label
  ].map(value => String(value || '').trim()).filter(Boolean)));
  const customerName = customerIdentityCandidates[0] || 'Unbekannt';

  return [{
    json: {
      stop: false,
      transaction_id: tx.id || tx.transaction_id,
      neonNumber: neonNumber,
      amount: amount,
      amountCents: amountCents,
      reference: reference,
      customer_name: customerName,
      customer_identity_candidates: customerIdentityCandidates,
      settled_at: tx.settled_at || tx.emitted_at || new Date().toISOString(),
      fuzzyMatch: fuzzyMatch,  // Flag für Fuzzy-Match
      raw_transaction: tx,
      respond: { status: 200 }
    }
  }];

} catch (error) {
  const input = $input.first().json;
  const rawData = JSON.stringify(input, null, 2).substring(0, 1500);

  return [{
    json: {
      stop: true,
      reason: 'unexpected_error',
      sendEmail: true,
      emailSubject: 'N8N Fehler: Unerwarteter Fehler bei Qonto Webhook',
      emailBody: `FEHLER: ${error.message}\n\nROHDATEN:\n${rawData}`,
      respond: { status: 200 }
    }
  }];
}

